Steps: Iterate through all possible subarrays of size ( k ) where ( l <= k <= r ). Compute the sum of each subarray. Check if the sum is greater than ( 0 ), and keep track of the minimum valid sum. Return the minimum valid sum or (-1) if no such subarray exists. Complexity: Time Complexity : (O(n^2)) (since we calculate the sum for all subarrays). Space Complexity : (O(1)) (no extra space used). Code: class Solution {
public: int minSumSubarray(vector<int>& nums, int l, int r) { int n = nums.size(); int minSum = INT_MAX; bool found = false; for (int start = 0; start < n; ++start) { int sum = 0; for (int end = start; end < n; ++end) { sum += nums[end]; int length = end - start + 1; if (length >= l && length <= r && sum > 0) { minSum = min(minSum, sum); found = true; } } } return found ? minSum : -1; }
};

